/**
 * Wink A/B Testing Tracker
 * ~3KB gzipped
 */
(function(window, document) {
    'use strict';

    var Wink = window.Wink || {};
    var config = window._winkConfig || {};
    var cookies = config.cookies || {};
    var queue = [];
    var flushTimer = null;
    var stopped = false;
    var endpoint = config.endpoint || '/wink/track';
    var batchInterval = (config.batchInterval || 5) * 1000;
    var noop = function() {};

    // Check Do Not Track
    function isDnt() {
        return navigator.doNotTrack === '1' || window.doNotTrack === '1';
    }

    function readCookie(name) {
        var parts = document.cookie ? document.cookie.split(/;\s*/) : [];
        for (var i = 0; i < parts.length; i++) {
            if (parts[i].indexOf(name + '=') === 0) {
                return parts[i].slice(name.length + 1);
            }
        }
        return null;
    }

    function writeCookie(name, value, maxAge) {
        document.cookie = name + '=' + value + '; path=/; max-age=' + maxAge + '; SameSite=Lax'
            + (cookies.domain ? '; domain=' + cookies.domain : '')
            + (location.protocol === 'https:' ? '; Secure' : '');
    }

    var consentCookie = cookies.consent || '_wink_consent';

    /**
     * Record the visitor's consent (call from a consent banner, or dispatch `wink:consent` on
     * window). With consent required, Wink identifies and tracks the visitor from the next page.
     */
    Wink.consent = function() {
        writeCookie(consentCookie, '1', (cookies.days || 365) * 86400);
    };

    /**
     * Withdraw consent: delete the consent and visitor cookies and stop tracking on this page.
     */
    Wink.revokeConsent = function() {
        writeCookie(consentCookie, '', 0);
        if (cookies.visitor) {
            writeCookie(cookies.visitor, '', 0);
        }
        stopped = true;
        queue.length = 0;
    };

    window.addEventListener('wink:consent', function() {
        Wink.consent();
    });

    window.Wink = Wink;

    if ((config.respectDnt && isDnt()) || (config.requireConsent && readCookie(consentCookie) !== '1')) {
        Wink.convert = noop;
        Wink.track = noop;
        return;
    }

    /**
     * Forward an event to GA4 / GTM, as it's queued (so nothing is lost when the page unloads).
     */
    function forward(evt) {
        if (config.enableGa4 && typeof gtag === 'function') {
            gtag('event', evt.type === 'conversion' ? 'wink_conversion' : 'wink_impression', {
                experiment: evt.experiment,
                variant: evt.variant,
                goal: evt.goal || undefined
            });
        }

        if (config.enableGtm && window.dataLayer) {
            window.dataLayer.push({
                event: config.gtmEventName || 'wink_experiment',
                winkExperiment: evt.experiment,
                winkVariant: evt.variant,
                winkEventType: evt.type,
                winkGoal: evt.goal || undefined
            });
        }
    }

    /**
     * Queue an event for batched sending.
     */
    function queueEvent(data) {
        if (stopped) return;
        queue.push(data);
        if (!flushTimer) {
            flushTimer = setTimeout(flush, batchInterval);
        }
    }

    /**
     * Flush queued events to the server.
     */
    function flush() {
        flushTimer = null;
        if (queue.length === 0) return;

        var events = queue.splice(0, queue.length);

        var xhr = new XMLHttpRequest();
        xhr.open('POST', endpoint, true);
        xhr.setRequestHeader('Content-Type', 'application/json');
        xhr.setRequestHeader('Accept', 'application/json');
        xhr.send(JSON.stringify({ events: events }));
    }

    function blocks() {
        return document.querySelectorAll('[data-wink-experiment]');
    }

    // The visitor ID a cache-safe block was assigned with, if there is one on the page.
    function pageVisitorId() {
        var el = document.querySelector('[data-wink-vid]');
        return el ? el.getAttribute('data-wink-vid') : undefined;
    }

    /**
     * Track an impression for an experiment. `visitorId` is the ID a cache-safe block was assigned
     * with in the browser; the server skips the event if its cookie says otherwise.
     */
    Wink.track = function(experimentHandle, variantHandle, visitorId) {
        var evt = {
            experiment: experimentHandle,
            variant: variantHandle,
            vid: visitorId || undefined,
            type: 'impression',
            url: window.location.href,
            referrer: document.referrer || null
        };
        forward(evt);
        queueEvent(evt);
    };

    /**
     * Record a conversion. It needn't be on a page with the experiment: the server counts it for
     * every running experiment with this goal that the visitor has seen.
     */
    Wink.convert = function(goalHandle, metadata) {
        if (!goalHandle) return;

        var onPage = blocks();
        onPage.forEach(function(el) {
            forward({
                type: 'conversion',
                experiment: el.getAttribute('data-wink-experiment'),
                variant: el.getAttribute('data-wink-variant'),
                goal: goalHandle
            });
        });
        if (onPage.length === 0) {
            forward({ type: 'conversion', goal: goalHandle });
        }

        queueEvent({
            type: 'conversion',
            goal: goalHandle,
            vid: pageVisitorId(),
            url: window.location.href,
            metadata: metadata || null
        });
    };

    // A goal the tracker detected itself belongs to one experiment, so it says which.
    function convertGoal(goal) {
        var el = document.querySelector('[data-wink-experiment="' + goal.experiment.replace(/["\\]/g, '\\$&') + '"]');
        var evt = {
            type: 'conversion',
            experiment: goal.experiment,
            variant: el ? el.getAttribute('data-wink-variant') : undefined,
            goal: goal.handle,
            vid: pageVisitorId(),
            url: window.location.href
        };
        forward(evt);
        queueEvent(evt);
    }

    /**
     * Auto-track impressions for elements with data-wink-experiment attribute.
     */
    function autoTrack() {
        // Cache-safe blocks reveal themselves inline; this catches any whose inline script didn't
        // run (a Content Security Policy without 'unsafe-inline', say).
        if (window.WinkDelivery) {
            window.WinkDelivery.resolveAll();
        }

        blocks().forEach(function(el) {
            var experimentHandle = el.getAttribute('data-wink-experiment');
            var variantHandle = el.getAttribute('data-wink-variant');
            if (experimentHandle && variantHandle) {
                Wink.track(experimentHandle, variantHandle, el.getAttribute('data-wink-vid'));
            }
        });
    }

    // Goals the tracker detects: page views by URL pattern, clicks and form submits by selector.
    // (Before 5.2.0 only clicks were detected, and only on elements present at load.)
    var goals = config.goals || (config.clickGoals || []).map(function(g) {
        return { type: 'click', handle: g.handle, target: g.selector, experiment: g.experiment };
    });

    // `*` matches anything. A pattern with `://` is matched against the whole URL, one with `?`
    // against the path and query, any other against the path.
    function matchesUrl(pattern) {
        var subject = pattern.indexOf('://') !== -1 ? location.href
            : location.pathname + (pattern.indexOf('?') !== -1 ? location.search : '');
        var trim = function(s) { return s.length > 1 ? s.replace(/\/$/, '') : s; };
        var source = pattern.split('*').map(function(part) {
            return part.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
        }).join('.*');
        return new RegExp('^' + trim(source) + '$').test(trim(subject));
    }

    function closest(el, selector) {
        try {
            return el && el.closest ? el.closest(selector) : null;
        } catch (e) {
            return null; // an invalid selector
        }
    }

    function initGoals() {
        goals.forEach(function(goal) {
            if (goal.type === 'pageview' && matchesUrl(goal.target)) {
                convertGoal(goal);
            }
        });

        ['click', 'submit'].forEach(function(type) {
            document.addEventListener(type, function(e) {
                goals.forEach(function(goal) {
                    if (goal.type === (type === 'click' ? 'click' : 'form_submit') && closest(e.target, goal.target)) {
                        convertGoal(goal);
                    }
                });
            }, true);
        });
    }

    // Flush on page unload. (A beacon goes as text/plain, which Craft doesn't parse, so these
    // events were lost before 5.1.0; a keepalive fetch sends JSON and survives the unload.)
    function onUnload() {
        if (queue.length > 0 && typeof fetch === 'function') {
            fetch(endpoint, {
                method: 'POST',
                credentials: 'same-origin',
                keepalive: true,
                headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
                body: JSON.stringify({ events: queue.splice(0, queue.length) })
            }).catch(function() {});
        }
    }

    // Initialize: impressions first, so a goal met on the experiment's own page follows its impression.
    function init() {
        autoTrack();
        initGoals();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    window.addEventListener('beforeunload', onUnload);
    window.addEventListener('pagehide', onUnload);

    // Force flush after batch interval even without new events
    setInterval(function() {
        if (queue.length > 0) flush();
    }, batchInterval);

})(window, document);
